INSERT INTO person_roster_completeness(organization_id,verification,version,membership_digest,source_reference,status,confirmed_membership_version,confirmed_by,confirmed_at,last_change_id,revision)
 VALUES(#{organizationId},'UNKNOWN',#{lastChangeId},NULL,#{sourceReference},#{status},#{confirmedMembershipVersion},#{confirmedBy},#{confirmedAt},#{lastChangeId},#{revision})
 ON DUPLICATE KEY UPDATE verification='UNKNOWN',membership_digest=NULL,version=#{lastChangeId},source_reference=#{sourceReference},status=#{status},confirmed_membership_version=#{confirmedMembershipVersion},confirmed_by=#{confirmedBy},confirmed_at=#{confirmedAt},last_change_id=#{lastChangeId},revision=#{revision}

mapper.select:
SELECT token FROM (
SELECT CONCAT('M:',id,':',person_id,':',valid_from,':',COALESCE(CAST(valid_until AS CHAR),''),':',COALESCE(ended_event_id,''),':',valid_from<=#{at},':',valid_until IS NOT NULL AND valid_until<=#{at}) token
FROM person_membership WHERE organization_id=#{organization}
UNION ALL
SELECT CONCAT('O:',id) token FROM person_foundation_event WHERE aggregate_type='ORGANIZATION' AND aggregate_id=#{organization}
AND JSON_UNQUOTE(JSON_EXTRACT(after_json,'$.status'))='INACTIVE'
) evidence ORDER BY token
